"""Recovery and reset functions. These functions are called from the top level IntegrityService
interface. They are not intended to be called directly from a test script"""

import interops.libraries.integrity.pages.service_screen as ServicePgObj
import interops.libraries.integrity.pages.storedbeam_menu as StoredBeamPgObj
import interops.libraries.integrity.pages.clinical_screen as ClinicalPgObj
import interops.libraries.integrity.pages.common_menu_bars as CommonMenuPgObj
import interops.libraries.icom.icom_th as IcomTest
from interops.libraries.integrity.linac_fkp import Linac_fkp
from typing import Optional as opt
from interops.libraries.integrity.sub_system_workflows.service_stored_beam_funcs import _service_funcs_open_stored_beam_menu
from interops.libraries.integrity.sub_system_workflows.service_functions_general_funcs import _service_funcs_open_select_machine_state_menu
import interops.libraries.integrity.sub_system_workflows.login_logoff_funcs as LoginFuncs
import squishtest3 as sq
import test
import logging


logger = logging.getLogger(__name__)

def _utility_recover_from_REP_failure(linac_id: str, ip_addr: str, linac_fkp_obj: opt[Linac_fkp]=None,
                                      icom: opt[IcomTest.iCOM_cat]=None) -> bool:
    '''
    Recover from failure in REP by performing an MLC reset

    Args:
        linac_id (str): Linac ID
        ip_addr (str): IP address of NRT
        linac_fkp_obj (Linac_fkp): Linac Fkp object for terminating beam
        icom (iCOM_cat): iCOM_cat object for clearing fields

    Returns:
        bool - True if REP recovery succeeded
    '''

    try:
        logger.info("recover_from_REP_failure starting")
        if linac_fkp_obj:
            linac_fkp_obj.press_terminate()
        rep = ClinicalPgObj.ReceiveExternalPrescription()
        menu = ClinicalPgObj.ClinicalMenuBar()
        if not icom:
            icom = IcomTest.iCOM_cat()
        icom.unconfirm_settings()
        icom.clear_field()
        icom.disconnect()
        rep.exit()
        sq.snooze(5)
        menu.log_off()
        for n in range(4):
            logger.info("recover_from_REP_failure attempt " + str(n))
            # TODO - Consider using login credentials from sharedconfig.cfg as per previous implementation, so these can be updated in one place
            if not LoginFuncs._login_check_current_user_and_clean_state("service", "service"):
                continue
            if not _service_funcs_open_select_machine_state_menu():
                continue
            sms = CommonMenuPgObj.select_machine_state()
            sq.snooze(5)
            if not sms.press_mlc_reset():
                sms.press_mlc_reset()
            sq.snooze(1)
            sms.close_page()
            '''loading a quick beam to try and clear any other inhibits'''
            StoredBeamPgObj.DeliverStoredBeam()
            if not _service_funcs_open_stored_beam_menu():
                continue
            exit_app = ServicePgObj.ServiceMenuBar()
            exit_app.log_off()
            # TODO - Consider using login credentials from sharedconfig.cfg as per previous implementation, so these can be updated in one place
            if not LoginFuncs._login_check_current_user_and_clean_state("clinical", "clinical"):
                continue
            menu.rep_prescription()
            sq.snooze(2)
            icom.set_server_connections(linac_id, ip_addr)
            logger.info("recover_from_REP_failure complete")
            return True
    except Exception as e:
        logger.exception("recover_from_REP_failure exception - " + str(e))
    logger.error("recover_from_REP_failure failed")
    return False


def _utility_reset_linac(login: bool = True, username: str = "service", password: str = "service") -> None:
    '''
    Resets the linac by selecting the MLC reset button from the
    the Select Machine State menu via the Service Functions menu

    Args:
        login (bool): Whether to login first before attempting
        reset
    '''

    logger.info("reseting linac")

    if login:
        LoginFuncs._login_check_current_user_and_clean_state(username, password)
    _service_funcs_open_select_machine_state_menu()
    select_machine_state = CommonMenuPgObj.select_machine_state()
    sq.snooze(5)
    if not select_machine_state.press_mlc_reset():
        select_machine_state.press_mlc_reset()
    sq.snooze(1)
    select_machine_state.close_page()